            net.minecraft.world.World world=(net.minecraft.world.World)worldFactory.newInstance(false);Field stateField=world.getClass().getDeclaredField("states"),tileField=world.getClass().getDeclaredField("tiles");stateField.setAccessible(true);tileField.setAccessible(true);((Map<BlockPos,net.minecraft.block.state.IBlockState>)stateField.get(world)).put(loaded.getPos(),blocks[blockIndex].getDefaultState());((Map<BlockPos,net.minecraft.tileentity.TileEntity>)tileField.get(world)).put(loaded.getPos(),loaded);loaded.setWorld(world);need(!loaded.validateParkingHoldInstalled()&&loaded.parkingHeld()&&!loaded.parkingQuarantined(),"Missing publication cells remain pending rather than invalid");loaded.target(false);need(loaded.parkingHeld()&&loaded.target(),"Pending native publication cannot be released by a command");for(VehicleStructure.Cell nativeCell:grid.cells)((Map<BlockPos,net.minecraft.block.state.IBlockState>)stateField.get(world)).put(nativeCell.pos,nativeCell.state);need(loaded.validateParkingHoldInstalled(),"Actual installed block geometry validates held grid phase");
